import{_ as o,c as t,o as n,ag as i}from"./chunks/framework.BSxiluPM.js";const e="/images/posts/amazonlinux2023-virtualbox/01.png",r="/images/posts/amazonlinux2023-virtualbox/02.png",s="/images/posts/amazonlinux2023-virtualbox/03.png",l="/images/posts/amazonlinux2023-virtualbox/04.png",m="/images/posts/amazonlinux2023-virtualbox/05.png",h=JSON.parse('{"title":"Amazon Linux 2023을 VirtualBox에서 실행하기","description":"","frontmatter":{"title":"Amazon Linux 2023을 VirtualBox에서 실행하기","date":"2024-01-29T23:00+0900","tags":["Oracle VirtualBox","AL2023"]},"headers":[],"relativePath":"posts/amazonlinux2023-virtualbox.md","filePath":"posts/amazonlinux2023-virtualbox.md","lastUpdated":1771482986000}'),u={name:"posts/amazonlinux2023-virtualbox.md"};function p(x,a,c,_,d,g){return n(),t("div",null,[...a[0]||(a[0]=[i('<p><a href="./amazonlinux2-virtualbox">Amazon Linux 2를 VirtualBox에서 실행하기</a>처럼 Amazon Linux 2023을 VM 가상머신으로 실행해보자.</p><h4 id="amazon-linux-2023-가상-머신-이미지-다운로드" tabindex="-1">Amazon Linux 2023 가상 머신 이미지 다운로드 <a class="header-anchor" href="#amazon-linux-2023-가상-머신-이미지-다운로드" aria-label="Permalink to &quot;Amazon Linux 2023 가상 머신 이미지 다운로드&quot;">​</a></h4><ul><li><a href="https://drive.google.com/file/d/17iBVLBLLJahQDb-3kgsWRCh72hzt1FIp/view?usp=sharing" target="_blank" rel="noreferrer">seed.io 부트 이미지</a></li><li><a href="https://cdn.amazonlinux.com/al2023/os-images/2023.3.20240122.0/kvm/" target="_blank" rel="noreferrer">Amazon Linux 2023 LTS 2023.3.20240122.0 kernel-6.1 x86_64 KVM image</a></li></ul><h4 id="가상-머신-만들기-및-실행" tabindex="-1">가상 머신 만들기 및 실행 <a class="header-anchor" href="#가상-머신-만들기-및-실행" aria-label="Permalink to &quot;가상 머신 만들기 및 실행&quot;">​</a></h4><p><img src="'+e+'" alt="1. 가상 머신 만들기"></p><p>새로 만들기 버튼을 눌러 가상 머신을 만들자. 리눅스 유형에 대한 운영 체제 종류는 공식 문서에 나와있지 않으나 Fedora 기반으로 알려져있으므로 Fedora (64-bit)를 선택했다. 그리고 가상 디스크는 미리 정의된 가상 머신으로 추가해야 한다. 위 스크린샷에 나와있듯이 <a href="https://cdn.amazonlinux.com/al2023/os-images/2023.3.20240122.0/" target="_blank" rel="noreferrer">Amazon Linux 2023 가상 머신 이미지</a> 페이지에서 다운로드 받은 KVM 이미지를 선택하면 된다.</p><p><img src="'+r+'" alt="2. 부팅 이미지 디스크 추가"></p><p>부팅 디스크 이미지 파일은 이전 <a href="./amazonlinux2-virtualbox">Amazon Linux 2를 VirtualBox에서 실행하기</a> 글에서 공유한 seed.iso 파일을 그대로 사용하도록 하자. 사용자 이름은 ec2-user 이며 초기 비밀번호는 amazon 이다.</p><p><img src="'+s+'" alt="3. 사용자 계정 구성"></p><p><img src="'+l+'" alt="4. ec2-user 로그인"></p><p>ec2-user 및 amazon 을 입력하면 Amazon Linux 2 와는 다르게 초기 비밀번호 변경을 요구한다. 위 스크린샷처럼 신규 비밀번호를 입력하고 로그인을 완료하자. 또한, 사용자 계정 구성이 올바르지 않게 될 수 있어 부팅 디스크로 사용한 seed.iso를 해제하지 않는 것을 권장한다.</p><p><img src="'+m+'" alt=""></p>',12)])])}const b=o(u,[["render",p]]);export{h as __pageData,b as default};
